if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$nome=trim($_POST['nome']??'');$email=trim($_POST['email']??'');$cpf=trim($_POST['cpf']??'');$matricula=trim($_POST['matricula']??'');$status=$_POST['status_financeiro']??'EM_DIA';$senha=(string)($_POST['senha']??'');if($nome===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$cpf===''||$matricula===''||strlen($senha)<8||!in_array($status,['EM_DIA','DEVEDOR','DESFILIADO'],true))throw new InvalidArgumentException('Preencha os campos corretamente. A senha deve ter pelo menos 8 caracteres.');$foto=null;if(isset($_FILES['foto'])&&$_FILES['foto']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['foto'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>2097152)throw new InvalidArgumentException('A foto deve ter no máximo 2 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new InvalidArgumentException('Use JPG, PNG ou WEBP.');$dir=__DIR__.'/../uploads/associados';if(!is_dir($dir))mkdir($dir,0755,true);$foto='associado_'.bin2hex(random_bytes(10)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$foto))throw new RuntimeException('Não foi possível guardar a foto.');}$telefone=trim($_POST['telefone']??'');$q=$pdo->prepare("INSERT INTO usuarios(nome,email,telefone,cpf,senha_hash,perfil,status_financeiro,matricula,data_filiacao,foto) VALUES(?,?,?,?,?, 'ASSOCIADO',?,?,CURDATE(),?)");$q->execute([$nome,$email,$telefone,$cpf,password_hash($senha,PASSWORD_ARGON2ID),$status,$matricula,$foto]);$id=(int)$pdo->lastInsertId();audit('CRIACAO_ASSOCIADO','usuarios',$id,null,['nome'=>$nome,'email'=>$email,'matricula'=>$matricula]);header('Location: '.app_url('admin/perfil.php?id='.$id.'&criado=1'));exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(PDOException $e){$error='E-mail, CPF ou matrícula já estão cadastrados.';}catch(Throwable $e){$error='Não foi possível criar o associado.';}}
